mapper.select:
SELECT smc.id, smc.code, smc.delivery_code as deliveryCode, smc.delivery_platform as deliveryPlatform, smc.delivery_shop_id as deliveryShopId, smc.delivery_shop_name as deliveryShopName, smc.shipment_code as shipmentCode, smc.approve_status as approveStatus, smc.create_status as createStatus, smc.invalid_status as invalidStatus, smc.dict_platform as dictPlatform, smc.shop_id as shopId, smc.shop_name as shopName, smc.so_id as soId, smc.so_code as soCode, smc.platform_code as platformCode, smc.track_no as trackNo, smc.bill_status as billStatus, smc.delivery_status as deliveryStatus, smc.logistics_channel_id as logisticsChannelId, smc.logistics_channel_name as logisticsChannelName, smcd.id as detailId, smcd.platform_spu_no as platformSpuNo, smcd.platform_sku_no as platformSkuNo, smcd.qty, smcd.delivery_qty as deliveryQty, smc.create_time as createTime, smc.approve_time as approveTime, smc.delivery_time as deliveryTime, smc.create_user_name as createUserName, smc.approve_user_name as approveUserName, smc.remark, smc.sign_order_error as signOrderError, smc.has_outstock as hasOutstock FROM so_multi_channel smc LEFT JOIN so_multi_channel_detail smcd on smcd.main_id=smc.id and smcd.is_deleted=false WHERE ${params.sqlMap.default} and smc.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
smc.create_time DESC

SELECT approve_status AS tabFlag, count(*) AS count FROM so_multi_channel WHERE is_deleted=FALSE
${params.permissionSql}
GROUP BY approve_status
